-- Migração aditiva: preserva categorias e produtos existentes.
create table if not exists public.departments(id uuid primary key default gen_random_uuid(),category_id uuid not null references public.categories(id) on delete restrict,name text not null,created_at timestamptz not null default now());
create unique index if not exists departments_category_name_unique on public.departments(category_id,lower(name));
alter table public.products add column if not exists category_id uuid references public.categories(id) on delete set null;
alter table public.products add column if not exists department_id uuid references public.departments(id) on delete set null;
create index if not exists products_category_id_idx on public.products(category_id);
create index if not exists products_department_id_idx on public.products(department_id);
insert into public.categories(name) select v.name from (values ('Chocolates'),('Laticínios'),('Panificação'),('Recheios e cremes'),('Confeitaria e decoração'),('Embalagens'),('Frutas, grãos e coco'),('Food service'),('Utensílios e formas'),('Bebidas e bomboniere')) v(name) where not exists(select 1 from public.categories c where lower(trim(c.name))=lower(trim(v.name)));
update public.products p set category_id=c.id from public.categories c where p.category_id is null and lower(trim(p.sector))=lower(trim(c.name));
insert into public.departments(category_id,name) select c.id,v.name from public.categories c cross join (values ('Barras, gotas e granulados de chocolate'),('Chocolate em pó, cacau e achocolatados'),('Coberturas fracionadas')) v(name) where lower(trim(c.name))=lower(trim('Chocolates')) and not exists(select 1 from public.departments d where d.category_id=c.id and lower(trim(d.name))=lower(trim(v.name)));
insert into public.departments(category_id,name) select c.id,v.name from public.categories c cross join (values ('Compostos e bases lácteas'),('Creme de leite'),('Leite condensado'),('Leite e leite em pó'),('Manteiga'),('Queijos, requeijão e cream cheese')) v(name) where lower(trim(c.name))=lower(trim('Laticínios')) and not exists(select 1 from public.departments d where d.category_id=c.id and lower(trim(d.name))=lower(trim(v.name)));
insert into public.departments(category_id,name) select c.id,v.name from public.categories c cross join (values ('Desmoldantes'),('Farinhas, amidos e polvilho'),('Fermentos, melhoradores e aditivos'),('Margarinas, gorduras e óleos'),('Misturas e pré-misturas')) v(name) where lower(trim(c.name))=lower(trim('Panificação')) and not exists(select 1 from public.departments d where d.category_id=c.id and lower(trim(d.name))=lower(trim(v.name)));
insert into public.departments(category_id,name) select c.id,v.name from public.categories c cross join (values ('Chantilly e cremes culinários'),('Doce de leite e goiabada'),('Recheios e coberturas cremosas')) v(name) where lower(trim(c.name))=lower(trim('Recheios e cremes')) and not exists(select 1 from public.departments d where d.category_id=c.id and lower(trim(d.name))=lower(trim(v.name)));
insert into public.departments(category_id,name) select c.id,v.name from public.categories c cross join (values ('Açúcares, glacê e xaropes'),('Confeitos, granulados e crocantes'),('Corantes, aromas e essências'),('Pastas e fondant'),('Pós para preparo, bases e gelatinas')) v(name) where lower(trim(c.name))=lower(trim('Confeitaria e decoração')) and not exists(select 1 from public.departments d where d.category_id=c.id and lower(trim(d.name))=lower(trim(v.name)));
insert into public.departments(category_id,name) select c.id,v.name from public.categories c cross join (values ('Bolos e tortas'),('Caixas e potes'),('Fitas, laços e acabamento'),('Forminhas'),('Forneáveis, isopor e bandejas'),('Sacos, sacolas, papel e filmes')) v(name) where lower(trim(c.name))=lower(trim('Embalagens')) and not exists(select 1 from public.departments d where d.category_id=c.id and lower(trim(d.name))=lower(trim(v.name)));
insert into public.departments(category_id,name) select c.id,v.name from public.categories c cross join (values ('Castanhas, nozes e amêndoas'),('Cereais e grãos'),('Coco'),('Frutas secas e em calda')) v(name) where lower(trim(c.name))=lower(trim('Frutas, grãos e coco')) and not exists(select 1 from public.departments d where d.category_id=c.id and lower(trim(d.name))=lower(trim(v.name)));
insert into public.departments(category_id,name) select c.id,v.name from public.categories c cross join (values ('Azeites e vinagres'),('Batata, frios e congelados'),('Conservas'),('Maionese, ketchup e molhos'),('Massas e grãos'),('Temperos e caldos')) v(name) where lower(trim(c.name))=lower(trim('Food service')) and not exists(select 1 from public.departments d where d.category_id=c.id and lower(trim(d.name))=lower(trim(v.name)));
insert into public.departments(category_id,name) select c.id,v.name from public.categories c cross join (values ('Bicos, cortadores e modelagem'),('Descartáveis e uniformes'),('Espátulas, batedores e acessórios'),('Formas e assadeiras'),('Máquinas e kits')) v(name) where lower(trim(c.name))=lower(trim('Utensílios e formas')) and not exists(select 1 from public.departments d where d.category_id=c.id and lower(trim(d.name))=lower(trim(v.name)));
insert into public.departments(category_id,name) select c.id,v.name from public.categories c cross join (values ('Bebidas'),('Biscoitos, balas e doces')) v(name) where lower(trim(c.name))=lower(trim('Bebidas e bomboniere')) and not exists(select 1 from public.departments d where d.category_id=c.id and lower(trim(d.name))=lower(trim(v.name)));
alter table public.departments enable row level security;
drop policy if exists "Macrofood departments public read" on public.departments;
create policy "Macrofood departments public read" on public.departments for select to anon,authenticated using(true);
drop policy if exists "Macrofood departments admin manage" on public.departments;
create policy "Macrofood departments admin manage" on public.departments for all to authenticated using(exists(select 1 from public.profiles p where p.id=auth.uid() and p.role='admin')) with check(exists(select 1 from public.profiles p where p.id=auth.uid() and p.role='admin'));
drop policy if exists "Macrofood categories public read" on public.categories;
create policy "Macrofood categories public read" on public.categories for select to anon,authenticated using(true);
drop policy if exists "Macrofood categories admin manage" on public.categories;
create policy "Macrofood categories admin manage" on public.categories for all to authenticated using(exists(select 1 from public.profiles p where p.id=auth.uid() and p.role='admin')) with check(exists(select 1 from public.profiles p where p.id=auth.uid() and p.role='admin'));
